"""Typed data models representing all database entities."""

from datetime import datetime
from typing import Any, Dict, List, Optional
from pydantic import BaseModel, Field


class ResearchPlan(BaseModel):
    """Structured research plan generated by the planning model."""
    core_question: str
    scope: str = ""
    definitions: Dict[str, str] = Field(default_factory=dict)
    subquestions: List[str] = Field(default_factory=list)
    search_angles: List[str] = Field(default_factory=list)
    primary_source_targets: List[str] = Field(default_factory=list)
    independent_source_targets: List[str] = Field(default_factory=list)
    community_source_targets: List[str] = Field(default_factory=list)
    counterargument_targets: List[str] = Field(default_factory=list)
    temporal_constraints: Optional[str] = None
    required_evidence_criteria: List[str] = Field(default_factory=list)


class SourceRecord(BaseModel):
    """Source item in the database."""
    id: Optional[int] = None
    run_id: str
    url: str
    canonical_url: str
    final_url: str = ""
    domain: str
    title: str = ""
    publisher: str = ""
    author: str = ""
    published_date: str = ""
    discovered_by_query_id: str = ""
    source_category: str = "unknown"  # primary, secondary, community, opposing, unknown
    source_tier: str = "Tier D"        # Tier A, Tier B, Tier C, Tier D
    fetch_status: str = "discovered"   # discovered, queued, fetching, fetched, permanent_failure, retryable_failure, blocked
    extraction_status: str = "pending" # pending, extracted, failed, no_content
    http_status: int = 0
    content_hash: str = ""
    error_reason: str = ""


class SourceContentRecord(BaseModel):
    """Stored original extracted text and metadata."""
    id: Optional[int] = None
    source_id: int
    run_id: str
    extracted_text: str
    extraction_method: str = "trafilatura"
    word_count: int = 0
    char_count: int = 0
    content_hash: str


class EvidenceRecord(BaseModel):
    """Verified evidence item."""
    id: str
    run_id: str
    source_id: int
    candidate_claim: str
    exact_quote: str
    quote_start_offset: int = -1
    quote_end_offset: int = -1
    claim_type: str = "direct_fact"
    evidence_type: str = "empirical"
    attribution: str = ""
    published_date: str = ""
    time_period: str = ""
    geographic_scope: str = ""
    metrics_data: str = "{}"
    surrounding_context: str = ""
    quote_valid: bool = False
    support_status: str = "unverified"
    verification_reason: str = ""
    verification_model: str = ""
    is_verified: bool = False


class ClaimRecord(BaseModel):
    """Synthesized claim linked to multiple evidence items."""
    id: str
    run_id: str
    cluster_title: str
    claim_text: str
    claim_category: str = "single_source"
    independent_sources_count: int = 1
    has_contradictions: bool = False
    status: str = "active"


class ContradictionRecord(BaseModel):
    """Disputed or contradictory findings."""
    id: str
    run_id: str
    claim_a_id: str = ""
    claim_b_id: str = ""
    evidence_a_id: str
    evidence_b_id: str
    description: str
    topic_facet: str = ""


class ResearchRunRecord(BaseModel):
    """Top-level research run tracking."""
    id: str
    question: str
    scope: str = ""
    status: str = "created"
    phase: str = "initialization"
    target_sources: int = 100
    max_rounds: int = 3
    current_round: int = 1
    model_id: str
    verifier_model_id: str
    report_path: str = ""
    stats_json: str = "{}"
    error_message: str = ""
    created_at: Optional[datetime] = None
    updated_at: Optional[datetime] = None
    completed_at: Optional[datetime] = None

